entries[12718] = { ["name"] = "Goblinscher Schutzhelm", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (8), Citrin , Elementarfeuer (4)\nGoblinscher Schutzhelm\nWird beim Aufheben gebunden\nKopf Stoff\n44 Rüstung\n+15 Feuerwiderstand\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Absorbiert 300 bis 500 Punkt(e) Feuerschaden. Hält 1 Min. lang an. (1 Stunde Abklingzeit)" }
entries[12719] = { ["name"] = "Explosiver Pfeil", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchneidenpfeil (100), Robustes Sprengpulver (2), Mithrilbarren (2)" }
