entries[12736] = { ["name"] = "Mithrildrachling beschwören", ["text"] = "Sofort 1 Stunde Abklingzeit\nDer Mithrildrachling wird 1 Min. lang zum Leben erweckt und verteidigt Euch." }
entries[12737] = { ["name"] = "Frostblitz", ["text"] = "90 Mana\nWirken in 3 sek.\nVerursacht Frostschaden bei in der Nähe befindlichen Feinden und verringert 4 Sek. lang ihr Bewegungstempo." }
