entries[12739] = { ["name"] = "Schattenblitz", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
