entries[12741] = { ["name"] = "Fluch der Schwäche", ["text"] = "105 Mana\nSofort\nVerringert den von in der Nähe befindlichen Feinden zugefügten körperlichen Schaden 2 Min. lang um 1 Punkt(e). Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[12742] = { ["name"] = "Feuerbrand", ["text"] = "95 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt einen Feind und fügt ihm dann 21 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
