entries[12745] = { ["name"] = "Manabrand", ["text"] = "Wirken in 3 sek.\nTrifft in der Nähe befindliche Feinde mit Antimanablitzen. Für jeden von einem Ziel abgezogenen Manapunkt erleidet das Ziel 0.5 Punkt(e) Schaden." }
entries[12746] = { ["name"] = "Leerwandler beschwören", ["text"] = "100% von Grundmana\nSofort\nReagenzien:\nSeelensplitter\nBeschwört 1 Leerwandler als Begleitung für den Zaubernden bis zur Freigabe." }
