entries[12748] = { ["name"] = "Frostnova", ["text"] = "75 Mana\nSofort\nVerursacht Frostschaden bei in der Nähe befindlichen Feinden und macht sie bis zu 5 Sek. lang bewegungsunfähig." }
entries[12749] = { ["name"] = "Mechanischer Mithrildrachling", ["text"] = "Sofort 1 Stunde Abklingzeit\nAktiviert Euren mechanischen Mithrildrachling, 1 Min. lang für Euch zu kämpfen. Benötigt eine Stunde als Abklingzeit, bevor ein erneuter Einsatz möglich wird." }
