entries[12754] = { ["name"] = "Der Große", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Goblin-Raketentreibstoff , Robustes Dynamit (6), Instabiler Auslöser\n(2)\nBenötigt Ingenieurskunst\n(225)\nBenutzen: Fügt 340 bis 460 Feuerschaden zu und betäubt Ziele 5 Sek. lang in einem Umkreis von 10 Metern. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[12755] = { ["name"] = "Goblin-Bombenspender", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse (2), Robustes Sprengpulver (4), Echtsilberbarren (6), Instabiler Auslöser , Genaues Zielfernrohr (2)\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(230)\nBenutzen: Lässt eine mobile Bombe entstehen, die den nächstbefindlichen Feind angreift, explodiert und dabei 315 bis 385 Punkt(e) Feuerschaden verursacht. (30 Min Abklingzeit)" }
entries[12758] = { ["name"] = "Goblin-Raketenhelm", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGoblinscher Schutzhelm , Goblin-Raketentreibstoff (4), Mithrilbarren (4), Instabiler Auslöser\nGoblin-Raketenhelm\nWird beim Anlegen gebunden\nKopf Stoff\n50 Rüstung\n+15 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(235)\nBenutzen: Einen Feind attackieren und ihn für 30 Sekunden außer Gefecht setzen. Ihr werdet ebenfalls niedergeschlagen und für kurze Zeit betäubt. Jeglicher erlittener Schaden wird das Ziel wiederbeleben. (20 Min Abklingzeit)" }
entries[12759] = { ["name"] = "Gnomentodesstrahl", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Instabiler Auslöser , Essenz des Untodes , Sekret des Untodes (4), Veredelter Mithrilzylinder\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Der Todesstrahl benötigt einige Zeit, um sich mit Eurer Lebenskraft aufzuladen und feuert dann einen Energiestoß auf Euren Gegner ab. (5 Min Abklingzeit)\n\"Verwendung dieses Geräts kann zum Tod oder zu schweren Verletzungen führen.\"" }
entries[12760] = { ["name"] = "Goblinsche Pioniersprengladung", ["text"] = "Wirken in 25 sek.\nReagenzien:\nMagiestoff , Robustes Sprengpulver (3), Instabiler Auslöser\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Explodiert bei Auslösung und verursacht 450 bis 750 Punkt(e) Feuerschaden bei allen in der Nähe befindlichen feindlichen Einheiten und 375 bis 625 Punkt(e) Schaden bei Euch. (5 Min Abklingzeit)" }
